script:
function search(ctx, query, page) {
  var html = ctx.http.get('/search?q=' + ctx.url.encode(query) + '&page=' + page);
  return ctx.html(html).select('.comic-card').map(function(item) {
    return {
      title: item.selectText('.title'),
      url: item.attr('data-url'),
      cover: item.selectAttr('img', 'src'),
      tags: item.select('.tag').map(function(tag) { return tag.text(); })
    };
  });
}

function detail(ctx, url) {
  var doc = ctx.html(ctx.http.get(url));
  return {
    title: doc.selectText('h1'),
    author: doc.selectText('.author'),
    description: doc.selectText('.description'),
    cover: doc.selectAttr('img.cover', 'src'),
    chapters: doc.select('.chapter').map(function(item) {
      return { title: item.selectText('.chapter-title'), url: item.attr('data-url') };
    })
  };
}

function pages(ctx, url) {
  return ctx.html(ctx.http.get(url)).select('.page').map(function(item) {
    return { url: item.attr('data-src') || item.attr('src'), text: item.text() };
  });
}
